#!/bin/bash
# Static checks on the built image (no VM needed).
IMG=${1:-localhost/kantanos:latest}
podman run --rm --entrypoint bash "$IMG" -c '
fail=0
check() { if eval "$2" >/dev/null 2>&1; then echo "PASS  $1"; else echo "FAIL  $1"; fail=1; fi; }
K=$(ls /usr/lib/modules | head -n1)
I=/usr/lib/modules/$K/initramfs.img
echo "initramfs: $(du -h $I | cut -f1)"
check "os-release says KantanOS"            "grep -q \"^NAME=\\\"KantanOS\\\"\" /usr/lib/os-release"
check "os-release ID still bazzite"         "grep -q ^ID=bazzite /usr/lib/os-release"
check "default look is org.kantanos"        "grep -q LookAndFeelPackage=org.kantanos.desktop /etc/xdg/kdeglobals"
check "look-and-feel layout present"        "test -f /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/layouts/org.kde.plasma.desktop-layout.js"
check "colour schemes for every look"       "for l in \$(cat /usr/share/kantanos/looks/order); do test -s /usr/share/color-schemes/Kantan\${l^}.colors && test -s /usr/share/kantanos/looks/\$l/wallpaper.png && test -s /usr/share/kantanos/looks/\$l/logo.png || exit 1; done"
check "default look is Light"               "grep -q ColorScheme=KantanLight /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/defaults && test \"\$(HOME=/tmp/fmtest kantan-look current)\" = light"
check "wallpaper present"                   "test -s /usr/share/wallpapers/KantanOS/contents/images/3840x2160.png"
check "launcher icon present"               "test -s /usr/share/icons/hicolor/64x64/apps/kantanos.png"
check "plymouth default is kantanos"        "test \"\$(plymouth-set-default-theme)\" = kantanos"
check "initramfs is a valid image"          "lsinitrd $I | grep -q systemd"
check "initramfs has ostree"                "lsinitrd $I | grep -q ostree-prepare-root"
check "initramfs has kantanos splash"       "lsinitrd $I | grep -q themes/kantanos/watermark.png"
check "fcitx5 + mozc installed"             "rpm -q fcitx5 fcitx5-mozc"
check "fcitx5 wayland launcher exists"      "test -f /usr/share/applications/fcitx5-wayland-launcher.desktop"
check "Japanese locale installed"           "locale -a | grep -q -i ja_JP.utf8"
check "Inter font installed"                "fc-list | grep -q -i \"Inter Variable\""
check "mpv installed"                       "rpm -q mpv"
check "ffmpeg has h264/hevc/av1 decoders"   "ffmpeg -hide_banner -decoders | grep -E -q \" hevc \" && ffmpeg -hide_banner -decoders | grep -q \" h264 \" && ffmpeg -hide_banner -decoders | grep -q av1"
check "ffmpeg has ac3/eac3/dts/truehd"      "for c in ac3 eac3 dca truehd; do ffmpeg -hide_banner -decoders | grep -q \" \$c \" || exit 1; done"
check "ujust recipes parse"                 "just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-hdr-on"
check "lock/login wallpaper is KantanOS"     "grep -q -E \"wallpapers/KantanOS|kantanos/looks/.*/lock.png\" /etc/xdg/kscreenlockerrc"
check "boot splash kernel args set"         "grep -q rhgb /usr/lib/bootc/kargs.d/10-kantanos.toml"
check "login screen wallpaper is KantanOS"   "grep -q -E \"wallpapers/KantanOS|kantanos/looks/.*/lock.png\" /usr/lib/plasmalogin/defaults.conf"
check "no Bazzite announcements autostart"  "test ! -e /etc/xdg/autostart/bazzite-announcement.desktop"
check "welcome autostart is KantanOS"       "grep -q KantanOS /etc/skel/.config/autostart/bazzite-portal.desktop"
check "glass panel theme present"           "test -s /usr/share/plasma/desktoptheme/KantanGlass/translucent/widgets/panel-background.svg"
check "starter-app service enabled"         "systemctl is-enabled kantanos-flatpak-setup.service"
check "starter-app script executable"       "test -x /usr/libexec/kantanos/flatpak-setup"
check "Steam does not autostart"            "test ! -e /etc/skel/.config/autostart/steam.desktop"
check "Welcome tasks open windows, not terminals" "python3 /usr/libexec/kantanos/install-window --self-test | grep -q ok && grep -q \"install-window install org.mozilla\" /usr/share/yafti/yafti.yml && ! grep -q xdg-terminal-exec.,$ /usr/bin/yafti_gtk.py && python3 /usr/libexec/kantanos/task-window --self-test | grep -q ok && python3 /usr/libexec/kantanos/update-window --self-test | grep -q ok && test -x /usr/libexec/uupd-update && grep -q update-window /usr/share/yafti/yafti.yml && grep -q \"nas-connect --window\" /usr/share/yafti/yafti.yml && test \"$(grep -c Press.Enter /usr/share/yafti/yafti.yml)\" -le 1"
check "welcome app is KantanOS"             "grep -q KantanOS /usr/share/yafti/yafti.yml && grep -q KantanOS /usr/bin/yafti_gtk.py && ! grep -q -i bazzite /usr/share/yafti/yafti.yml"
check "welcome definition is valid YAML"    "python3 /usr/libexec/kantanos/check-welcome"
check "kantan-app helper works"             "kantan-app status org.example.Nothing | grep -q uninstall"
check "file manager defaults present"       "grep -q ShowFullPath=false /etc/xdg/dolphinrc"
check "file permissions sane"               "test \$(stat -c %a /etc/xdg/kwinrc) = 644"
check "file manager toolbar layout present" "grep -q commandToolBar /etc/skel/.local/share/kxmlgui5/dolphin/dolphinui.rc"
check "file manager saved layout present"  "grep -q ^State= /etc/skel/.local/state/dolphinstaterc"
check "file manager sidebar setup runs"    "test -x /usr/libexec/kantanos/files-setup && grep -q files-setup /etc/xdg/plasma-workspace/env/kantanos-files.sh"
mkdir -p /tmp/fmtest/Documents
check "sidebar setup writes the sidebar"   "HOME=/tmp/fmtest XDG_DATA_HOME=/tmp/fmtest/d /usr/libexec/kantanos/files-setup; grep -q applications:/ /tmp/fmtest/d/user-places.xbel && xmllint --noout /tmp/fmtest/d/user-places.xbel"
check "file manager window rule present"   "grep -q wmclass=dolphin /etc/xdg/kwinrulesrc"
check "file manager is named Files"        "grep -q ^Name=Files /usr/share/applications/org.kde.dolphin.desktop"
check "mode chooser program is valid"      "test -x /usr/libexec/kantanos/modes && python3 -m py_compile /usr/libexec/kantanos/modes"
check "mode chooser has its four modes"    "test \$(ls /usr/share/kantanos/modes/*.mode | wc -l) -ge 4 && test -s /usr/share/kantanos/looks/light/icons/tv.svg"
check "mode chooser screen loads"          "HOME=/tmp/fmtest QT_QPA_PLATFORM=offscreen QT_QUICK_BACKEND=software timeout 10 /usr/libexec/kantanos/modes; test \$? = 124"
check "mode chooser starts at login"       "grep -q -- --login /etc/xdg/autostart/kantanos-modes.desktop"
check "mode chooser is on the dock"        "grep -q kantanos-modes.desktop /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/layouts/org.kde.plasma.desktop-layout.js && test -f /usr/share/applications/kantanos-modes.desktop"
check "mode chooser window rule present"   "grep -q wmclass=kantanos-modes /etc/xdg/kwinrulesrc"
check "AI shortcuts: maker works without an AI" "python3 -m py_compile /usr/share/kantanos/modes/shortcut_ai.py && HOME=/tmp/satest python3 /usr/share/kantanos/modes/shortcut_ai.py watch netflix | grep -q netflix.com && grep -q addSuggested /usr/share/kantanos/modes/ui/Main.qml"
check "Shortcuts: an app name needs no AI, web addresses can be looked up" "HOME=/tmp/satest python3 /usr/share/kantanos/modes/shortcut_ai.py Plexamp | grep -q com.plexamp.Plexamp && grep -q def\ find_sites /usr/share/kantanos/modes/shortcut_ai.py && grep -q findSite /usr/share/kantanos/modes/ui/Main.qml && grep -q findSite /usr/libexec/kantanos/modes"
check "backups: restic, rclone, program, timer" "command -v restic && command -v rclone && python3 -m py_compile /usr/libexec/kantanos/backup /usr/share/kantanos/backup/engine.py && HOME=/tmp/bktest /usr/libexec/kantanos/backup run | grep -q not.set.up && grep -q OnCalendar=.:0/30 /usr/lib/systemd/user/kantanos-backup.timer && test -f /usr/share/applications/kantanos-backup.desktop"
check "starter apps wait and run at idle priority" "grep -q IOSchedulingClass=idle /usr/lib/systemd/system/kantanos-flatpak-setup.service && grep -q sleep.180 /usr/lib/systemd/system/kantanos-flatpak-setup.service"
check "login display server has a long start limit" "grep -q TimeoutStartSec=300 /usr/lib/systemd/user/plasma-login-kwin_wayland.service.d/10-kantanos.conf && test -f /usr/lib/systemd/user/plasma-login-kwin_wayland.service"
check "bluetooth boot argument is built in" "grep -q bluetooth.disable_ertm=1 /usr/lib/bootc/kargs.d/10-kantanos.toml"
check "Welcome suggests Install, never Remove"   "! grep -q -E id:.\"install\" /usr/share/yafti/yafti.yml && grep -q remove-app /usr/share/yafti/yafti.yml"
check "installed systems switched to local clock once" "systemctl is-enabled kantanos-local-clock.service && test -x /usr/sbin/hwclock -o -x /usr/bin/hwclock"
check "hardware clock in local time (like Windows)" "grep -qx LOCAL /etc/adjtime"
check "app installs wait for other downloads"      "grep -q wait_for_others /usr/bin/kantan-app && grep -q yield_to_user /usr/libexec/kantanos/flatpak-setup"
check "HDMI audio keep-awake rule present"  "grep -q suspend-timeout-seconds.=.0 /usr/share/wireplumber/wireplumber.conf.d/60-kantanos-hdmi-keepalive.conf"
check "speaker test recipes parse"         "just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-speaker-test && just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-hdmi-keepalive"
check "KantanOS Dock widget installed"      "test -s /usr/share/plasma/plasmoids/org.kantanos.dock/contents/ui/main.qml && jq -e .KPlugin.Id /usr/share/plasma/plasmoids/org.kantanos.dock/metadata.json"
check "new layout uses the KantanOS Dock"   "grep -q org.kantanos.dock /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/layouts/org.kde.plasma.desktop-layout.js"
check "existing accounts get the new dock"  "test -s /usr/share/plasma/shells/org.kde.plasma.desktop/contents/updates/kantanos-dock-1.js"
check "dock panel is see-through, no blur"  "grep -q south-center /usr/share/plasma/desktoptheme/KantanGlass/translucent/widgets/panel-background.svg && grep -q south-hint-top-margin /usr/share/plasma/desktoptheme/KantanGlass/translucent/widgets/panel-background.svg"
check "genie minimize, smooth maximize/open" "grep -q magiclampEnabled=true /etc/xdg/kwinrc && grep -q squashEnabled=false /etc/xdg/kwinrc"
check "Spotlight-style search on Win+Space"  "grep -q FreeFloating=true /etc/xdg/krunnerrc && grep -q Meta+Space /usr/share/kglobalaccel/org.kde.krunner.desktop"
check "Force Quit app and shortcut"         "python3 -m py_compile /usr/libexec/kantanos/force-quit && grep -q Ctrl+Alt+Esc /usr/share/kglobalaccel/kantanos-force-quit.desktop"
check "search shows KantanOS, not Bazzite"   "grep -q \"KantanOS Welcome Items\" /usr/lib64/qt6/plugins/kf6/krunner/krunner-yafti.so && ! grep -q \"Bazzite Portal Actions\" /usr/lib64/qt6/plugins/kf6/krunner/krunner-yafti.so"
check "folder sizes: Filelight + right-click" "command -v filelight && grep -q filelight /usr/share/kio/servicemenus/kantanos-folder-sizes.desktop && grep -q qdirstat /usr/share/yafti/yafti.yml"
check "light looks dim the lock screen"     "test -s /usr/share/kantanos/looks/light/lock.png && grep -q looks/light/lock.png /etc/xdg/kscreenlockerrc && grep -q looks/light/lock.png /usr/lib/plasmalogin/defaults.conf"
check "root login warning in the chooser"   "grep -q createAccount /usr/libexec/kantanos/modes && grep -q rootBanner /usr/share/kantanos/modes/ui/Main.qml"
check "Wake-on-LAN on by default"           "grep -q wake-on-lan=magic /usr/lib/NetworkManager/conf.d/60-kantanos-wake-on-lan.conf && just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-wake-info"
check "phone link app and Welcome entry"    "test -f /usr/share/applications/org.kde.kdeconnect.app.desktop && grep -q kdeconnect-app /usr/share/yafti/yafti.yml"
check "NAS helper present"                  "bash -n /usr/libexec/kantanos/nas-connect && just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-nas-connect && command -v mount.cifs && command -v smbclient"
check "Windows programs: Wine installed"   "command -v wine && rpm -q wine-mono && test -x /usr/bin/kantan-windows"
check "Wine menu entries hidden"     "! grep -L ^NoDisplay=true /usr/share/applications/wine-*.desktop | grep -q ."
check "Windows VM: QEMU, TPM, firmware, tools" "command -v qemu-system-x86_64 swtpm xorriso xfreerdp && test -f /usr/share/edk2/ovmf/OVMF_CODE_4M.secboot.qcow2 && test -f /usr/share/edk2/ovmf/OVMF_VARS_4M.secboot.qcow2 && test -x /usr/libexec/kantanos/windows-vm && test -f /usr/lib/systemd/user/kantanos-windows-vm.service"
check "Windows VM: setup answers are valid XML" "xmllint --noout /usr/share/kantanos/windows-vm/autounattend.xml"
check "Windows VM: firmware and TPM boot"   "cd /tmp && timeout 180 /usr/libexec/kantanos/windows-vm _selftest | grep -q SELFTEST.PASS"
check "HDMI Dolby/DTS pass-through allowed"  "grep -q TrueHD /usr/share/wireplumber/wireplumber.conf.d/61-kantanos-hdmi-passthrough.conf && grep -q audio-spdif /usr/share/applications/kantanos-movie-player.desktop && command -v mpv"
check "new helper commands parse"           "just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-reset-dock && just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-admin-password && bash -n /usr/libexec/kantanos/dock-repair"
check "Qt for Python present (chooser, Force Quit)" "python3 -c \"import PySide6.QtQuick\""
check "KantanOS Weather widget in the top bar" "jq -e .KPlugin.Id /usr/share/plasma/plasmoids/org.kantanos.weather/metadata.json && grep -q org.kantanos.weather /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/layouts/org.kde.plasma.desktop-layout.js && test -s /usr/share/plasma/shells/org.kde.plasma.desktop/contents/updates/kantanos-weather-1.js"
check "KantanOS Stats widget in the top bar" "jq -e .KPlugin.Id /usr/share/plasma/plasmoids/org.kantanos.stats/metadata.json && grep -q org.kantanos.stats /usr/share/plasma/look-and-feel/org.kantanos.desktop/contents/layouts/org.kde.plasma.desktop-layout.js && test -s /usr/share/plasma/shells/org.kde.plasma.desktop/contents/updates/kantanos-stats-1.js && test -d /usr/lib64/qt6/qml/org/kde/ksysguard/sensors && command -v lscpu"
check "restart into Windows: tile, command, no-password rule" "test -s /usr/share/kantanos/modes/50-windows.mode && test -x /usr/libexec/kantanos/restart-windows && test -x /usr/libexec/kantanos/set-boot-next && grep -q set-boot-next /usr/share/polkit-1/actions/org.kantanos.restart-windows.policy && test -s /usr/share/kantanos/looks/light/icons/restart.svg && command -v efibootmgr && bash -n /usr/libexec/kantanos/restart-windows"
check "Helper watch: offers help when an app crashes" "test -s /etc/xdg/autostart/kantanos-helper-watch.desktop && python3 -m ast /usr/libexec/kantanos/helper-watch >/dev/null && test -s /usr/share/kantanos/helper/watch-ignore && command -v notify-send"
check "drive names: system drive KantanOS, helper partitions hidden" "test -s /usr/lib/udev/rules.d/90-kantanos-drive-names.rules && systemctl is-enabled kantanos-drive-label.service && bash -n /usr/libexec/kantanos/drive-label && bash -n /usr/libexec/kantanos/files-setup"
check "apps may ask for the location"        "grep -q xdg-desktop-portal /etc/geoclue/conf.d/90-kantanos.conf && just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-set-location"
check "firewall uses the strict KantanOS zone"  "grep -q ^DefaultZone=KantanOS /etc/firewalld/firewalld.conf && firewall-offline-cmd --zone=KantanOS --list-services | grep -q kdeconnect && ! firewall-offline-cmd --zone=KantanOS --list-ports | grep -q 1025-65535"
check "virus scanning: ClamAV + Files menu"  "command -v clamscan && systemctl is-enabled clamav-freshclam.service && test -x /usr/libexec/kantanos/virus-scan && grep -q virus-scan /usr/share/kio/servicemenus/kantanos-virus-scan.desktop && bash -n /usr/libexec/kantanos/virus-scan && grep -q PathChanged=%h/Downloads /usr/lib/systemd/user/kantanos-virus-watch.path && grep -q -- --new-downloads /usr/lib/systemd/user/kantanos-virus-watch.service && ! test -e /etc/systemd/user/default.target.wants/kantanos-virus-watch.path && grep -q -- --auto-setting /usr/share/yafti/yafti.yml && grep -q -- --quarantine /usr/share/yafti/yafti.yml"
check "KantanOS Helper and local AI present"  "python3 -m py_compile /usr/libexec/kantanos/helper && command -v ollama && test -f /usr/lib/ollama/vulkan/libggml-vulkan.so && test -s /usr/share/licenses/ollama/VERSION && grep -q OLLAMA_NO_CLOUD=1 /usr/lib/systemd/user/kantanos-ollama.service && test -f /usr/lib/systemd/user/kantanos-ollama.service && test -f /usr/share/applications/kantanos-helper.desktop"
check "Kan-chan character and voice engine"   "test -s /usr/share/kantanos/helper/characters/kan-chan/idle.svg && test -s /usr/share/kantanos/helper/characters/kan-chan/talk2.svg && test -s /usr/share/kantanos/helper/characters/kan-chan/listen.svg && python3 -c \"import piper, PySide6.QtSvg, pywhispercpp.model; from kokoro_onnx import Kokoro; import misaki, jaconv\" && echo こんにちは | mecab | grep -q コンニチハ && grep -q kokoro-jf_tebukuro /usr/share/kantanos/helper/characters/kan-chan/character.json && command -v pw-play && command -v pw-record && grep -q \"class NameDialog\" /usr/libexec/kantanos/helper"
check "Kan-chan full length in the Helper" "test -s /usr/share/kantanos/helper/characters/kan-chan/looks/doctor/full/idle.png && python3 -m json.tool /usr/share/kantanos/helper/characters/kan-chan/looks/doctor/full/faces.json >/dev/null && test $(ls /usr/share/kantanos/helper/characters/kan-chan/looks/*/full/idle.png | wc -l) -ge 25 && grep -q full=True /usr/libexec/kantanos/helper"
check "Kan-chan companion app (memory, window)" "QT_QPA_PLATFORM=offscreen HOME=/tmp/kc timeout 60 /usr/libexec/kantanos/kanchan --self-test | grep -q ok && test -s /usr/share/applications/kantanos-kanchan.desktop && test -s /usr/share/icons/hicolor/256x256/apps/kantanos-kanchan.png && test ! -e /usr/share/icons/hicolor/scalable/apps/kantanos-kanchan.svg && test -s /usr/share/kantanos/helper/kanchan-worried.png && grep -q kanchan-worried.png /usr/libexec/kantanos/helper-watch"
check "Kan-chan email and calendar (add-on, reminders)"  "cd /usr/share/kantanos/kanchan && HOME=/tmp/km python3 mail.py | grep -q ok && python3 agenda.py | grep -q ok && python3 -m json.tool mailaddon/manifest.json >/dev/null && test -s mailaddon/background.js && python3 -m py_compile /usr/libexec/kantanos/kanchan-remind && HOME=/tmp/kr /usr/libexec/kantanos/kanchan-remind && grep -q OnCalendar=.:0/5 /usr/lib/systemd/user/kantanos-kanchan-remind.timer && grep -q Meta+K /usr/share/kglobalaccel/kantanos-kanchan-listen.desktop"
check "Watch TV (player, sorting, guide, recorder)" "rpm -q mpv-libs && command -v ffmpeg && cd /usr/share/kantanos/tv && python3 lineup.py --self-test | grep -q ok && python3 guide.py | grep -q ok && python3 recorder.py --self-test | grep -q ok && python3 -c \"import mpvwidget; mpvwidget.lib()\" && QT_QPA_PLATFORM=offscreen HOME=/tmp/tvt timeout 60 /usr/libexec/kantanos/tv --self-test | grep -q ok && systemctl --global is-enabled kantanos-tv-recorder.service && grep -q /usr/libexec/kantanos/tv /usr/share/kantanos/modes/20-tv.mode && ! grep -q Hidden=true /usr/share/kantanos/modes/20-tv.mode && test -f /usr/share/applications/kantanos-tv.desktop"
check "Retro Games (Boxshelf setup)" "QT_QPA_PLATFORM=offscreen HOME=/tmp/rg timeout 60 /usr/libexec/kantanos/retro --self-test | grep -q ok && grep -q /usr/libexec/kantanos/retro /usr/share/kantanos/modes/40-retro.mode && test -f /usr/share/applications/kantanos-retro.desktop && test -e /usr/lib64/libfuse.so.2"
check "Wakaru TV (download setup)" "QT_QPA_PLATFORM=offscreen HOME=/tmp/wk timeout 60 /usr/libexec/kantanos/wakaru-tv --self-test | grep -q ok && grep -q /usr/libexec/kantanos/wakaru-tv /usr/share/kantanos/modes/25-wakaru.mode && test -f /usr/share/applications/kantanos-wakaru-tv.desktop && test -f /usr/share/kantanos/wakaru/wakaru-tv.png"
check "Vintage Computers (app, tile)" "QT_QPA_PLATFORM=offscreen HOME=/tmp/vc timeout 60 /usr/libexec/kantanos/vintage --self-test | grep -q ok && grep -q /usr/libexec/kantanos/vintage /usr/share/kantanos/modes/45-vintage.mode && test -f /usr/share/applications/kantanos-vintage.desktop && test -s /usr/share/kantanos/looks/light/icons/vintage.svg"
check "Android apps (Waydroid setup, .apk opens)" "command -v waydroid && test -x /usr/libexec/kantanos/android-setup && bash -n /usr/libexec/kantanos/android-setup && QT_QPA_PLATFORM=offscreen HOME=/tmp/an timeout 60 kantan-android --self-test | grep -q ok && grep -q vnd.android.package-archive=kantanos-android-install.desktop /etc/xdg/mimeapps.list && test -f /usr/share/polkit-1/actions/org.kantanos.android-setup.policy && test -f /usr/share/applications/kantanos-android.desktop"
check "Android apps hidden from the menu and Welcome" "grep -q ^NoDisplay=true /usr/share/applications/kantanos-android.desktop && grep -q ^NoDisplay=true /usr/share/applications/Waydroid.desktop && ! grep -q kantan-android /usr/share/yafti/yafti.yml"
check "Memory running out closes one app, not the whole PC" "systemctl is-enabled systemd-oomd.service && grep -q ^ManagedOOMMemoryPressure=kill /usr/lib/systemd/system/user@.service.d/20-kantanos-oomd.conf && grep -q ^ManagedOOMSwap=kill /usr/lib/systemd/system/-.slice.d/20-kantanos-oomd.conf && grep -q lru_gen/min_ttl_ms /usr/lib/tmpfiles.d/kantanos-memory.conf && test -L /etc/systemd/user/graphical-session.target.wants/kantanos-memory-notice.service && /usr/libexec/kantanos/memory-notice --self-test"
check "Updates window says what is in the update" "grep -q ^Exec=/usr/libexec/kantanos/update-window /usr/share/applications/io.github.rfrench3.bazzite-updater.desktop && jq -e length\>0 /usr/share/kantanos/whats-new.json && jq -e all\(.[]\;.id\ and\ .title\) /usr/share/kantanos/whats-new.json && /usr/libexec/kantanos/update-window --self-test && command -v skopeo"
check "Smart home (thermostat widget, Home Assistant setup)" "test -x /usr/bin/kantan-home && test -x /usr/libexec/kantanos/home-setup && bash -n /usr/libexec/kantanos/home-setup && QT_QPA_PLATFORM=offscreen HOME=/tmp/hm timeout 60 kantan-home --self-test | grep -q ok && test -f /usr/share/plasma/plasmoids/org.kantanos.home/contents/ui/main.qml && test -f /usr/share/polkit-1/actions/org.kantanos.home-setup.policy && grep -q AutoUpdate=registry /usr/share/kantanos/home/kantanos-homeassistant.container && test -f /usr/share/applications/kantanos-home.desktop"
check "Letters and documents (OCR, explain, check, read aloud)" "tesseract --list-langs | grep -qx jpn && command -v pdftotext && QT_QPA_PLATFORM=offscreen HOME=/tmp/dc timeout 120 kantan-docs --self-test | grep -q ok && test -f /usr/share/kio/servicemenus/kantanos-docs.desktop && test -f /usr/share/applications/kantanos-docs.desktop"
check "Picture helper (describe, find, make, fix)" "/usr/libexec/kantanos/sd-cli --help 2>&1 | grep -c diffusion-model && test -s /usr/share/licenses/kantanos-sd/stable-diffusion.cpp.txt && grep -q OLLAMA_CONTEXT_LENGTH /usr/lib/systemd/user/kantanos-ollama.service && QT_QPA_PLATFORM=offscreen HOME=/tmp/pc timeout 120 kantan-pictures --self-test | grep -q ok && test -f /usr/share/kio/servicemenus/kantanos-pictures.desktop && test -f /usr/share/applications/kantanos-pictures.desktop"
check "Recipe book (import, scale, cook)" "QT_QPA_PLATFORM=offscreen HOME=/tmp/rc timeout 120 kantan-recipes --self-test | grep -q ok && test -f /usr/share/kio/servicemenus/kantanos-recipes.desktop && test -f /usr/share/applications/kantanos-recipes.desktop && test -f /usr/share/sounds/freedesktop/stereo/alarm-clock-elapsed.oga"
check "Game Mode library sync (Heroic, Lutris)" "python3 /usr/libexec/kantanos/games-sync --self-test | grep -q ok && grep -q PathChanged=%h/.local/share/lutris/pga.db /usr/lib/systemd/user/kantanos-games-sync.path && grep -q ExecStart=/usr/libexec/kantanos/games-sync /usr/lib/systemd/user/kantanos-games-sync.service && test -L /etc/systemd/user/default.target.wants/kantanos-games-sync.path && grep -q games-sync /usr/share/kantanos/modes/30-game.mode"
check "Installed PCs: first account and start-up entry" "rpm -q plasma-setup efibootmgr && test -L /etc/systemd/system/multi-user.target.wants/plasma-setup.service && grep -q first-user-check /usr/lib/systemd/system/plasma-setup.service.d/10-kantanos.conf && bash -n /usr/libexec/kantanos/first-user-check && bash -n /usr/libexec/kantanos/boot-entry && test -L /etc/systemd/system/multi-user.target.wants/kantanos-boot-entry.service"
check "Files is called Files (menus and window titles)" "grep -q \"exec /usr/libexec/kantanos/dolphin-bin\" /usr/bin/dolphin && test -x /usr/libexec/kantanos/dolphin-bin && test -s /usr/share/locale/kantanos/LC_MESSAGES/dolphin.mo && test -s /usr/share/locale/kantanos_ja/LC_MESSAGES/dolphin.mo && grep -q ^Name=Files /usr/share/applications/org.kde.dolphin.desktop"
check "Block bad sites (list, categories, safe look-up, window)" "python3 /usr/share/kantanos/site-blocker/blocker.py --self-test | grep -q ok && QT_QPA_PLATFORM=offscreen HOME=/tmp/sb timeout 60 /usr/libexec/kantanos/site-blocker --self-test | grep -q ok && /usr/libexec/kantanos/site-blocker-apply status | grep -q safe_dns && test -L /etc/systemd/system/timers.target.wants/kantanos-site-blocker.timer && grep -q auth_admin_keep /usr/share/polkit-1/actions/org.kantanos.site-blocker.policy && test -f /usr/share/applications/kantanos-site-blocker.desktop && rpm -q systemd-resolved"
check "Safe picture (1080p first on big screens)" "/usr/libexec/kantanos/safe-picture --self-test | grep -q ok && systemctl is-enabled kantanos-safe-picture.service && test -f /usr/lib/udev/rules.d/90-kantanos-safe-picture.rules"
check "screen reader speaks with the natural voice" "python3 /usr/libexec/kantanos/piper-speech --self-test | grep -q ok && grep -q ^DefaultModule.kantanos-piper /etc/speech-dispatcher/speechd.conf && grep -q piper-speech /etc/speech-dispatcher/modules/kantanos-piper.conf && command -v espeak-ng"
check "8-bit colour on Intel screens without HDR" "python3 /usr/libexec/kantanos/colour-depth --self-test | grep -q ok && grep -q colour-depth /etc/xdg/autostart/kantanos-colour-depth.desktop"
check "NVIDIA services quiet on PCs without NVIDIA" "grep -q 0x10de /usr/lib/systemd/system/nvidia-cdi-refresh.service.d/kantanos-only-with-nvidia.conf && grep -q -F -- \"nvidia0 ] || exit 0\" /etc/xdg/autostart/nvidia-settings-load.desktop"
check "Easier to see and hear (Orca, window)" "command -v orca && QT_QPA_PLATFORM=offscreen HOME=/tmp/ax timeout 60 /usr/libexec/kantanos/accessibility --self-test | grep -q ok && test -f /usr/share/applications/kantanos-accessibility.desktop"
check "Kan-chan eyes (OpenCV face models)"  "cd /usr/share/kantanos/kanchan && python3 -c \"import vision; assert vision.available(); vision.Faces()\" && test -s /usr/share/licenses/kantanos-kanchan-vision/SFace-LICENSE"
check "Kan-chan noticing (opt-in service)"  "python3 -m py_compile /usr/libexec/kantanos/kanchan-notice && test -f /usr/lib/systemd/user/kantanos-kanchan-notice.service && python3 -c \"import dbus, psutil\""
check "Kan-chan desktop buddy widget"  "test -s /usr/share/plasma/plasmoids/org.kantanos.kanchan/metadata.json && grep -q kstart /usr/share/plasma/plasmoids/org.kantanos.kanchan/contents/ui/main.qml && command -v kstart"
check "Kan-chan outfits (season, time, weather)" "python3 /usr/share/kantanos/helper/looks.py --self-test | grep -q ok && python3 -m json.tool /usr/share/kantanos/helper/characters/kan-chan/when.json && test -s /usr/share/kantanos/helper/characters/kan-chan/looks/everyday/idle.png && test -s /usr/share/kantanos/helper/characters/kan-chan/looks/everyday/talk1.png && test \$(ls -d /usr/share/kantanos/helper/characters/kan-chan/looks/*/ | wc -l) -ge 25 && for d in /usr/share/kantanos/helper/characters/kan-chan/looks/*/; do test \$(ls \$d*.png | wc -l) -eq 8 || exit 1; done"
check "Windows drive notice says KantanOS"  "grep -q sender=.KantanOS /usr/libexec/ntfs-exfat-monitor-script"
check ".exe and .msi open with kantan-windows" "grep -q x-msi=kantanos-windows-program.desktop /etc/xdg/mimeapps.list && grep -q x-ms-dos-executable=kantanos-windows-program.desktop /etc/xdg/mimeapps.list"
check "32-bit Windows programs allowed (SELinux)" "matchpathcon /usr/lib64/wine-wow64/wine/i386-windows/ntdll.dll | grep -q textrel_shlib_t"
check "daily update timer enabled"    "systemctl is-enabled uupd.timer"
check "update recipes parse"                "just --justfile /usr/share/ublue-os/justfile --list | grep -q kantan-undo-update"
. /usr/lib/os-release
if [ -n "$KANTAN_IMAGE" ]; then
check "image label says latest, banner says KantanOS" "jq -e \".\\\"image-tag\\\" == \\\"latest\\\"\" /usr/share/ublue-os/image-info.json && grep -q KantanOS /usr/share/ublue-os/motd/template.md"
check "image knows its update address"      "grep -q \"docker://$KANTAN_IMAGE\" /usr/share/ublue-os/image-info.json"
check "signing public key present"          "grep -q \"BEGIN PUBLIC KEY\" /etc/pki/containers/kantanos.pub"
check "only signed updates are accepted"    "jq -e --arg r \"$KANTAN_IMAGE\" \".transports.docker[\\\$r][0].type == \\\"sigstoreSigned\\\"\" /etc/containers/policy.json"
check "signatures are looked up"            "grep -q \"$KANTAN_IMAGE\" /etc/containers/registries.d/kantanos.yaml"
else
echo "NOTE  no update address in this build (tools/registry.conf is empty)"
fi
ls /usr/share/applications | grep -i fcitx
exit $fail
'
